// WF-6 — log to swarm_log (E1-4)
// Input: {task_id, workflow, gate, verdict, duration_ms} or full state
const inp = $input.first().json;
const row = {
  task_id: inp.task_id || inp.state?.task_id || 'unknown',
  workflow: inp.workflow || inp.gate || 'unknown',
  gate: inp.gate || inp.workflow || 'unknown',
  verdict: inp.verdict || inp.status || 'unknown',
  duration_ms: inp.duration_ms || 0
};
return [{ json: row }];
